window.MASTER4_MUSEOS_REAL = [{ "id": "mhn", "nombre": "Museu Histórico Nacional", "subtitulo": "La historia de Brasil en el corazón de Río de Janeiro", "categoria": "Historia de Brasil", "descripcion": "El Museu Histórico Nacional es uno de los espacios más importantes de Río de Janeiro para conocer la historia de Brasil a través de objetos, documentos, obras de arte y testimonios materiales de diferentes épocas. Creado en 1922, durante las celebraciones del centenario de la Independencia de Brasil, el museo ocupa un conjunto arquitectónico histórico en el Centro de Río y reúne un acervo de más de 300.000 piezas.", "historia": "El Museu Histórico Nacional nació en 1922, durante las celebraciones del centenario de la Independencia de Brasil. Río de Janeiro era entonces la capital federal y el país buscaba construir y preservar una memoria nacional. El museo fue creado oficialmente el 2 de agosto de 1922 y abrió sus puertas al público el 12 de octubre del mismo año.", "direccion": "Praça Marechal Âncora, s/nº – Centro – Rio de Janeiro – RJ", "horario": "Consultar el horario vigente antes de la visita, ya que puede variar según exposiciones, obras, mantenimiento y actividades de la institución.", "valor": "", "imagen": "" }, { "id": "folclore-edison-carneiro", "nombre": "Museu de Folclore Edison Carneiro", "subtitulo": "Un viaje por las fiestas, creencias, artes y tradiciones populares de Brasil", "categoria": "Folclore y cultura popular", "descripcion": "El Museu de Folclore Edison Carneiro es uno de los espacios más interesantes de Río para conocer la enorme diversidad cultural de Brasil. Sus colecciones reúnen objetos relacionados con fiestas populares, religiosidad, música, literatura de cordel, artesanía, juguetes, vestimentas, cerámica, esculturas y formas de expresión creadas por comunidades de diferentes regiones del país.", "historia": "El museo fue creado en 1968 y forma parte del Centro Nacional de Folclore e Cultura Popular, institución vinculada al Instituto do Patrimônio Histórico e Artístico Nacional. Su misión no consiste solamente en guardar objetos, sino también en investigar, documentar y difundir las múltiples expresiones de la cultura popular brasileña.", "direccion": "Rua do Catete, 179 – Catete – Rio de Janeiro – RJ", "horario": "Martes a viernes, de 10:00 a 18:00. Sábados, domingos y feriados, consulta el horario vigente antes de ir, ya que las fuentes institucionales pueden mostrar modificaciones. Cerrado los lunes.", "valor": "", "imagen": "" }, { "id": "musal", "nombre": "Museu Aeroespacial – MUSAL", "subtitulo": "Aviones históricos y la evolución de la aviación brasileña", "categoria": "Aviación, historia y tecnología", "descripcion": "El Museu Aeroespacial, conocido como MUSAL, es el mayor y más importante museo dedicado a la aviación militar de Brasil. Funciona en Campo dos Afonsos, uno de los lugares fundamentales para el nacimiento y desarrollo de la aviación brasileña. Sus grandes hangares reúnen aeronaves, motores, uniformes, documentos, fotografías y objetos históricos.", "historia": "La idea de crear un museo aeronáutico brasileño comenzó a tomar fuerza durante la década de 1940, cuando surgió la preocupación por conservar aeronaves, documentos y objetos vinculados con los primeros años de la aviación nacional. Después de años de organización y recuperación de piezas, el Museu Aeroespacial fue inaugurado el 18 de octubre de 1976.", "direccion": "Av. Marechal Fontenelle, 2000 – Campo dos Afonsos – Rio de Janeiro – RJ", "horario": "Martes a domingo, de 9:00 a 16:00. El portón cierra a las 15:30, por lo que debes llegar antes de ese horario. Los miércoles, de 8:00 a 9:00, existe un horario exclusivo para personas con discapacidades intelectuales o mentales y sus acompañantes.", "valor": "", "imagen": "" }, { "id": "acude", "nombre": "Museu do Açude", "subtitulo": "Arte, arquitectura y naturaleza dentro de la Floresta da Tijuca", "categoria": "Arte, coleccionismo y naturaleza", "descripcion": "El Museu do Açude ocupa una antigua residencia de Raymundo Ottoni de Castro Maya en el Alto da Boa Vista, rodeada por jardines y Mata Atlántica. Es un museo diferente: la experiencia no se limita a las salas interiores, porque las construcciones, senderos, vegetación, fuentes, azulejos y obras instaladas al aire libre forman parte del recorrido.", "historia": "Raymundo Ottoni de Castro Maya fue empresario, coleccionista y una figura importante de la vida cultural carioca del siglo XX. Reunió obras brasileñas y europeas, mobiliario, objetos decorativos, libros, azulejos y piezas de arte oriental. También participó en proyectos relacionados con la preservación del patrimonio y la valorización cultural de Río de Janeiro.", "direccion": "Estrada do Açude, 764 – Alto da Boa Vista – Rio de Janeiro – RJ", "horario": "Atención: la información oficial señala mantenimiento y posibles cierres temporales. Los jardines suelen funcionar de 9:00 a 17:00. Las exposiciones interiores, cuando están abiertas, funcionan normalmente de 11:00 a 17:00, excepto los martes. Confirma el estado el mismo día antes de desplazarte.", "valor": "", "imagen": "" }, { "id": "povos-indigenas", "nombre": "Museu Nacional dos Povos Indígenas", "subtitulo": "Diversidad, memoria y culturas vivas de los pueblos originarios de Brasil", "categoria": "Pueblos indígenas y antropología", "descripcion": "El antiguo Museu do Índio, actualmente llamado Museu Nacional dos Povos Indígenas, es una institución de la Fundação Nacional dos Povos Indígenas dedicada a investigar, preservar y difundir la diversidad cultural de los pueblos originarios de Brasil. Su colección reúne objetos etnográficos, fotografías, películas, grabaciones, documentos y materiales lingüísticos.", "historia": "El museo fue creado en 1953 por el antropólogo Darcy Ribeiro. Desde sus orígenes buscó combatir las visiones estereotipadas que presentaban a los pueblos indígenas como sociedades pertenecientes únicamente al pasado.", "direccion": "Rua das Palmeiras, 55 – Botafogo – Rio de Janeiro – RJ", "horario": "Atención al público de lunes a viernes, de 9:00 a 17:00. Los jardines pueden visitarse, pero el casarón y el principal espacio expositivo continúan cerrados por obras. Confirma la programación antes de ir.", "valor": "", "imagen": "" }, { "id": "naval", "nombre": "Museu Naval", "subtitulo": "La formación de Brasil contada desde el mar", "categoria": "Historia naval y patrimonio marítimo", "descripcion": "El Museu Naval presenta la historia marítima y militar de Brasil mediante modelos de embarcaciones, pinturas, documentos, armamento, medallas, instrumentos de navegación y objetos recuperados de diferentes épocas. Se encuentra en la Praça XV, una zona estrechamente relacionada con el puerto y la historia política de Río.", "historia": "La navegación fue fundamental para la formación territorial, política y económica de Brasil. Por el mar llegaron expediciones, mercancías, migrantes y también invasores. La defensa de la extensa costa exigió la creación de fortificaciones, arsenales y fuerzas navales.", "direccion": "Rua Dom Manuel, 15 – Praça XV – Centro – Rio de Janeiro – RJ", "horario": "Jueves a domingo y feriados, de 13:00 a 17:00. Consulta posibles cierres extraordinarios antes de la visita.", "valor": "", "imagen": "" }, { "id": "villa-lobos", "nombre": "Museu Villa-Lobos", "subtitulo": "La vida y la obra de uno de los mayores compositores de Brasil", "categoria": "Música y memoria", "descripcion": "El Museu Villa-Lobos está dedicado a preservar y difundir la trayectoria de Heitor Villa-Lobos, compositor que transformó elementos de la música popular, indígena y académica en una obra reconocida internacionalmente. El museo conserva partituras, documentos, fotografías, objetos personales y registros sonoros.", "historia": "Heitor Villa-Lobos nació en Río de Janeiro en 1887. Desde joven tuvo contacto con instrumentos, músicos populares y diferentes ambientes culturales de la ciudad. Su obra combinó formación clásica con ritmos, sonidos y temas brasileños.", "direccion": "Rua Sorocaba, 200 – Botafogo – Rio de Janeiro – RJ", "horario": "Temporalmente cerrado. Consulta la reapertura en los canales oficiales antes de incluirlo en tu itinerario.", "valor": "", "imagen": "" }, { "id": "mar", "nombre": "Museu de Arte do Rio – MAR", "subtitulo": "Arte, ciudad y nuevas formas de mirar Río de Janeiro", "categoria": "Arte y cultura urbana", "descripcion": "El Museu de Arte do Rio, conocido como MAR, presenta exposiciones que relacionan arte, historia, identidad, territorio y vida urbana. Está situado en la Praça Mauá y ocupa un conjunto arquitectónico que une el Palacete Dom João VI con un edificio modernista mediante una gran cubierta ondulada.", "historia": "El MAR fue inaugurado el 1 de marzo de 2013 como parte del proceso de revitalización de la zona portuaria. Desde el comienzo se propuso pensar Río no solamente como una postal turística, sino como una ciudad marcada por encuentros, desigualdades, memorias y transformaciones.", "direccion": "Praça Mauá, 5 – Saúde – Rio de Janeiro – RJ", "horario": "Abierto de jueves a martes. Pabellón de exposiciones de 11:00 a 18:00, con último acceso a las 17:00. Cerrado los miércoles. Confirma posibles cierres temporales antes de ir.", "valor": "", "imagen": "" }, { "id": "maas", "nombre": "Museu Arquidiocesano de Arte Sacra – MAAS", "subtitulo": "Cinco siglos de fe, arte e historia religiosa de Río de Janeiro", "categoria": "Arte sacro e historia religiosa", "descripcion": "El Museu Arquidiocesano de Arte Sacra funciona en el subsuelo de la Catedral Metropolitana de São Sebastião. Su colección reúne pinturas, esculturas, imágenes religiosas, vestimentas litúrgicas, objetos de culto, documentos y piezas relacionadas con la historia de la Iglesia católica en Río de Janeiro.", "historia": "La formación del museo comenzó alrededor de 1950, cuando el padre Ivo Calliari inició la recolección de piezas por solicitud del cardenal Dom Jaime de Barros Câmara. El objetivo era proteger objetos históricos procedentes de iglesias, capillas e instituciones religiosas.", "direccion": "Av. República do Chile, 245 – Subsuelo de la Catedral Metropolitana – Centro – Rio de Janeiro – RJ", "horario": "Martes a viernes, de 9:00 a 16:00. Sábados, de 9:00 a 12:00. Domingos, de 10:00 a 13:00. Confirma posibles modificaciones por celebraciones religiosas.", "valor": "", "imagen": "" }, { "id": "amanha", "nombre": "Museu do Amanhã", "subtitulo": "Un museo para explorar el presente e imaginar los futuros posibles", "categoria": "Ciencia, innovación y sostenibilidad", "descripcion": "El Museu do Amanhã es un museo de ciencias diferente. En lugar de intentar predecir un único futuro, invita a reflexionar sobre las decisiones que tomamos en el presente y sus consecuencias para el planeta, la sociedad y las próximas generaciones.", "historia": "El Museu do Amanhã fue inaugurado en diciembre de 2015 como uno de los principales proyectos de transformación de la zona portuaria. Su creación ayudó a devolver la Praça Mauá a los peatones y convertir el área en uno de los circuitos culturales más visitados de Río.", "direccion": "Praça Mauá, 1 – Centro – Rio de Janeiro – RJ", "horario": "Jueves a martes, de 10:00 a 18:00. Último acceso a las 17:00. Cerrado los miércoles. El ingreso corresponde a un día y horario determinado.", "valor": "", "imagen": "" }, { "id": "museu-light", "nombre": "Museu Light da Energia", "subtitulo": "Experimentos interactivos para comprender la electricidad y la sostenibilidad", "categoria": "Ciencia, energía y educación", "descripcion": "El Museu Light da Energia es un espacio educativo e interactivo dedicado a explicar cómo se produce, distribuye y utiliza la energía. Sus experiencias combinan ciencia, historia, juegos y reflexiones sobre consumo responsable y sostenibilidad.", "historia": "La expansión de la electricidad transformó profundamente Río de Janeiro. La iluminación pública, los tranvías, las industrias, los elevadores y los aparatos domésticos cambiaron la forma de vivir y circular por la ciudad.", "direccion": "Av. Marechal Floriano, 168 – Centro – Rio de Janeiro – RJ", "horario": "Visitas de lunes a viernes, excepto feriados. Los horarios individuales publicados suelen ser 11:30, 12:30 y 15:30, pero pueden cambiar. Confirma la agenda antes de ir.", "valor": "", "imagen": "" }, { "id": "ihgb", "nombre": "Instituto Histórico e Geográfico Brasileiro – IHGB", "subtitulo": "Documentos, libros y objetos fundamentales para comprender la historia de Brasil", "categoria": "Historia, biblioteca y patrimonio documental", "descripcion": "El Instituto Histórico e Geográfico Brasileiro es una de las instituciones culturales más antiguas de Brasil. Fundado en 1838, conserva una biblioteca, un archivo y una colección museológica de enorme importancia para el estudio de la historia, la geografía y la formación del país.", "historia": "El IHGB fue fundado el 21 de octubre de 1838, durante el período regencial. Su creación estuvo inspirada en instituciones europeas dedicadas a reunir documentos, promover investigaciones y construir narrativas sobre la historia nacional.", "direccion": "Av. Augusto Severo, 8 – Glória – Rio de Janeiro – RJ", "horario": "Visitas individuales normalmente realizadas los martes, exclusivamente mediante agendamiento y confirmación del IHGB.", "valor": "", "imagen": "" }, { "id": "casa-deodoro", "nombre": "Casa Histórica de Deodoro", "subtitulo": "La casa donde se organizó el primer gobierno republicano de Brasil", "categoria": "Historia política y República", "descripcion": "La Casa Histórica de Deodoro conserva la memoria del marechal Manuel Deodoro da Fonseca, líder de la Proclamación de la República y primer presidente de Brasil. La residencia fue escenario de reuniones políticas decisivas y permite comprender los acontecimientos que pusieron fin al Imperio en 1889.", "historia": "Manuel Deodoro da Fonseca fue militar y una de las principales figuras del movimiento que proclamó la República el 15 de noviembre de 1889. Después de la caída de la monarquía, asumió la jefatura del gobierno provisional y posteriormente se convirtió en el primer presidente constitucional del país.", "direccion": "Praça da República, 197 – Centro – Rio de Janeiro – RJ", "horario": "Martes a domingo, de 9:00 a 16:00. Confirma posibles cierres por actividades militares o mantenimiento.", "valor": "", "imagen": "" }, { "id": "mnba", "nombre": "Museu Nacional de Belas Artes – MNBA", "subtitulo": "Una de las colecciones de arte más importantes de Brasil", "categoria": "Pintura, escultura y artes visuales", "descripcion": "El Museu Nacional de Belas Artes conserva una de las principales colecciones artísticas del país. Su acervo reúne pinturas, esculturas, dibujos, grabados, artes decorativas y obras relacionadas con la formación de las artes visuales brasileñas.", "historia": "Parte de los orígenes de la colección se relaciona con la llegada de la corte portuguesa a Río de Janeiro en 1808. Obras procedentes de Portugal y piezas incorporadas posteriormente ayudaron a formar las primeras colecciones artísticas oficiales de Brasil.", "direccion": "Av. Rio Branco, 199 – Cinelândia – Centro – Rio de Janeiro – RJ", "horario": "Apertura parcial. La exposición disponible suele funcionar de lunes a viernes, de 13:00 a 17:00, con acceso hasta las 16:30, y en fechas especiales como el segundo sábado del mes. Consulta obligatoriamente la programación vigente.", "valor": "", "imagen": "" }, { "id": "museu-republica", "nombre": "Museu da República – Palácio do Catete", "subtitulo": "Del lujo presidencial a uno de los capítulos más dramáticos de la historia de Brasil", "categoria": "República, política y residencia presidencial", "descripcion": "El Museu da República funciona en el Palácio do Catete, antigua sede de la Presidencia de Brasil. Sus habitaciones, salones, objetos, documentos y jardines permiten conocer la vida política republicana desde finales del siglo XIX hasta la transferencia de la capital a Brasilia.", "historia": "El edificio fue construido entre 1858 y 1867 como residencia de António Clemente Pinto, el Barão de Nova Friburgo. Su riqueza procedía principalmente de actividades agrícolas y comerciales desarrolladas durante el Imperio.", "direccion": "Rua do Catete, 153 – Catete – Rio de Janeiro – RJ", "horario": "Museo: miércoles a domingo, de 11:00 a 17:00. Jardines: todos los días, de 8:00 a 18:00. Confirma posibles cambios y cierres de salas.", "valor": "", "imagen": "" }, { "id": "mam-rio", "nombre": "Museu de Arte Moderna do Rio de Janeiro – MAM Rio", "subtitulo": "Arte moderna, arquitectura y jardines frente a la Baía de Guanabara", "categoria": "Arte moderna y contemporánea", "descripcion": "El MAM Rio es una de las instituciones artísticas más importantes de Brasil. Su edificio modernista, sus exposiciones, la Cinemateca y los jardines diseñados por Roberto Burle Marx forman un conjunto cultural integrado con el Parque do Flamengo y la Baía de Guanabara.", "historia": "El MAM Rio fue fundado en 1948 por empresarios, artistas, coleccionistas y críticos interesados en crear un espacio dedicado al arte moderno. Durante las décadas siguientes se convirtió en un importante punto de encuentro de la vanguardia brasileña.", "direccion": "Av. Infante Dom Henrique, 85 – Parque do Flamengo – Rio de Janeiro – RJ", "horario": "Miércoles a sábado, de 10:00 a 18:00. Domingos, de 10:00 a 11:00, horario exclusivo para personas con discapacidad intelectual, personas autistas o con hipersensibilidad; de 11:00 a 18:00, público general. Último acceso a las 17:30.", "valor": "", "imagen": "" }, { "id": "museu-pontal", "nombre": "Museu do Pontal", "subtitulo": "La mayor colección de arte popular brasileño en un museo rodeado de naturaleza", "categoria": "Arte popular y cultura brasileña", "descripcion": "El Museu do Pontal conserva una de las colecciones más importantes de arte popular de Brasil. Miles de obras creadas por artistas de diferentes regiones presentan fiestas, trabajos, creencias, personajes, animales, tradiciones y escenas de la vida cotidiana brasileña.", "historia": "El origen del museo está relacionado con el diseñador y coleccionista francés Jacques Van de Beuque. Después de establecerse en Brasil, recorrió diferentes regiones del país y comenzó a adquirir obras directamente de artistas populares.", "direccion": "Av. Célia Ribeiro da Silva Mendes, 3300 – Barra da Tijuca – Rio de Janeiro – RJ", "horario": "Jueves a domingo, de 10:00 a 18:00. Último acceso a las exposiciones a las 17:30. Los eventos pueden tener horarios y condiciones diferentes.", "valor": "", "imagen": "" }, { "id": "museu-samba", "nombre": "Museu do Samba", "subtitulo": "Memoria, resistencia y las voces que construyeron el samba carioca", "categoria": "Samba, carnaval y cultura afrobrasileña", "descripcion": "El Museu do Samba es un centro de memoria dedicado a preservar y difundir la historia del samba. Ubicado en Mangueira, cerca de uno de los territorios más simbólicos del carnaval carioca, reúne testimonios, fotografías, objetos, música y experiencias relacionadas con compositores, intérpretes, comunidades y escuelas de samba.", "historia": "El museo nació de iniciativas desarrolladas en Mangueira para preservar la memoria de las comunidades vinculadas con el samba. Su ubicación no es casual: el barrio está relacionado con compositores, intérpretes y con la Estação Primeira de Mangueira.", "direccion": "Rua Visconde de Niterói, 1296 – Mangueira – Rio de Janeiro – RJ", "horario": "Martes a sábado, de 10:00 a 17:00. Cerrado los domingos, lunes y feriados. Confirma posibles visitas mediadas y modificaciones.", "valor": "", "imagen": "" }, { "id": "muhcab", "nombre": "Museu da História e da Cultura Afro-Brasileira – MUHCAB", "subtitulo": "Memoria negra, ancestralidad y resistencia en el corazón de la Pequena África", "categoria": "Historia y cultura afrobrasileña", "descripcion": "El MUHCAB es un museo de vocación comunitaria dedicado a la historia, cultura, memoria y protagonismo de la población negra. Está situado en Gamboa, dentro del territorio conocido como Pequena África, una de las regiones fundamentales para comprender la formación cultural de Río de Janeiro.", "historia": "La zona portuaria recibió durante siglos a africanos esclavizados, trabajadores, libertos, migrantes y comunidades que transformaron profundamente la cultura carioca. El MUHCAB busca relacionar su sede con los lugares de memoria distribuidos por ese territorio.", "direccion": "Rua Pedro Ernesto, 80 – Gamboa – Rio de Janeiro – RJ", "horario": "Martes a domingo, de 10:00 a 17:00. La programación puede provocar cambios extraordinarios; confirma antes de ir.", "valor": "", "imagen": "" }, { "id": "chacara-ceu", "nombre": "Museu Chácara do Céu", "subtitulo": "Arte brasileño y europeo con una de las vistas más especiales de Santa Teresa", "categoria": "Arte, coleccionismo y arquitectura", "descripcion": "El Museu Chácara do Céu ocupa una antigua residencia de Raymundo Ottoni de Castro Maya en Santa Teresa. Su colección reúne arte brasileño, obras europeas, mobiliario, libros y objetos decorativos en una casa modernista rodeada de jardines y vistas hacia el Centro y la Baía de Guanabara.", "historia": "Castro Maya fue empresario, coleccionista y una figura importante de la vida cultural carioca. Reunió obras de diferentes épocas y participó en iniciativas de preservación y valorización del patrimonio de Río.", "direccion": "Rua Murtinho Nobre, 93 – Santa Teresa – Rio de Janeiro – RJ", "horario": "Lunes, miércoles, jueves, viernes y sábado, de 10:00 a 16:30. Cerrado los martes, domingos y feriados. También cierra durante Carnaval, Navidad y Año Nuevo.", "valor": "", "imagen": "" }, { "id": "benjamin-constant", "nombre": "Museu Casa de Benjamin Constant", "subtitulo": "La vida de uno de los principales ideólogos de la República brasileña", "categoria": "Historia política y residencia histórica", "descripcion": "El Museu Casa de Benjamin Constant funciona en la antigua residencia del militar, profesor y político Benjamin Constant Botelho de Magalhães, una de las figuras centrales del movimiento republicano brasileño. La casa conserva muebles, fotografías, documentos, libros y objetos familiares en medio de un gran parque de Santa Teresa.", "historia": "Benjamin Constant nació en 1836 y desarrolló una trayectoria como militar, profesor, matemático y político. Fue un importante divulgador del positivismo y defendió cambios en la educación y en la organización política de Brasil.", "direccion": "Rua Monte Alegre, 255 – Santa Teresa – Rio de Janeiro – RJ", "horario": "Casa histórica: martes a viernes, de 10:00 a 17:00. Sábados, domingos y feriados, de 13:00 a 17:00. El parque suele abrir diariamente de 8:00 a 17:00. Confirma posibles cambios.", "valor": "", "imagen": "" }, { "id": "mast", "nombre": "Museu de Astronomia e Ciências Afins – MAST", "subtitulo": "Astronomía, instrumentos científicos y noches de observación del cielo", "categoria": "Astronomía, ciencia y tecnología", "descripcion": "El MAST es un museo y centro de investigación dedicado a la historia de la ciencia, la astronomía y la preservación del patrimonio científico. Funciona en el histórico campus del antiguo Observatório Nacional, en São Cristóvão, y conserva telescopios, lunetas, instrumentos de medición, documentos y edificios científicos.", "historia": "La historia del lugar está vinculada con el desarrollo de la astronomía en Brasil. El Observatório Nacional tuvo su origen en el siglo XIX y se trasladó al Morro de São Januário durante las primeras décadas del siglo XX.", "direccion": "Rua General Bruce, 586 – Bairro Imperial de São Cristóvão – Rio de Janeiro – RJ", "horario": "Martes a viernes, normalmente de 9:00 a 17:00. Sábados, domingos y feriados, generalmente de 14:00 a 18:00. Algunas primeras miércoles del mes pueden tener programación nocturna. Confirma la agenda vigente.", "valor": "", "imagen": "" }, { "id": "museu-vida-fiocruz", "nombre": "Museu da Vida Fiocruz", "subtitulo": "Ciencia, salud y diversión dentro del histórico campus de Manguinhos", "categoria": "Ciencia, salud y educación", "descripcion": "El Museu da Vida Fiocruz es un espacio de divulgación científica que presenta temas relacionados con salud, biología, medicina, medio ambiente y sociedad. Sus exposiciones y actividades se distribuyen por el histórico campus de la Fundação Oswaldo Cruz, donde también se encuentra el famoso Castelo Mourisco.", "historia": "La Fundação Oswaldo Cruz tuvo su origen en los esfuerzos para combatir epidemias y mejorar la salud pública a comienzos del siglo XX. Científicos como Oswaldo Cruz desarrollaron investigaciones y campañas que transformaron la medicina brasileña.", "direccion": "Av. Brasil, 4365 – Manguinhos – Rio de Janeiro – RJ", "horario": "Martes a viernes, de 9:00 a 16:30. Sábados, de 10:00 a 16:00. Cerrado domingos y lunes. El Borboletário está temporalmente cerrado.", "valor": "", "imagen": "" }, { "id": "museu-flamengo", "nombre": "Museu Flamengo", "subtitulo": "Títulos, ídolos y la pasión del club más popular de Brasil", "categoria": "Fútbol y memoria deportiva", "descripcion": "El Museu Flamengo presenta la historia del Clube de Regatas do Flamengo mediante trofeos, camisetas, fotografías, documentos, objetos, videos y experiencias inmersivas. Funciona en la sede social de Gávea y recorre la trayectoria del club desde sus orígenes en el remo hasta sus grandes conquistas en el fútbol y otros deportes.", "historia": "El Flamengo fue fundado en 1895 como un club de remo. En aquella época, las regatas eran uno de los grandes acontecimientos deportivos y sociales de Río.", "direccion": "Av. Borges de Medeiros, 997 – Lagoa – Rio de Janeiro – RJ", "horario": "Todos los días, de 9:00 a 18:00. Último acceso a las 17:40. La bilhetería presencial funciona desde las 8:40.", "valor": "", "imagen": "" }, { "id": "museu-nacional-ufrj", "nombre": "Museu Nacional – UFRJ", "subtitulo": "Doscientos años de ciencia, historia y reconstrucción en el antiguo palacio imperial", "categoria": "Historia natural, arqueología y ciencia", "descripcion": "El Museu Nacional es la institución científica más antigua de Brasil y una de las más importantes de América Latina. Funciona en el Paço de São Cristóvão, antigua residencia de la familia imperial, dentro de Quinta da Boa Vista. Después del incendio de 2018, el museo atraviesa un extenso proceso de reconstrucción y reapertura gradual.", "historia": "El Museu Nacional fue creado en 1818 por el rey Dom João VI con el nombre de Museu Real. Su objetivo era promover el conocimiento científico y reunir colecciones de historia natural, arqueología, antropología y otras áreas.", "direccion": "Quinta da Boa Vista, s/nº – São Cristóvão – Rio de Janeiro – RJ", "horario": "Apertura parcial mediante exposiciones temporales. Las visitas suelen realizarse de martes a domingo, de 10:00 a 16:00, con último acceso a las 15:30. Consulta obligatoriamente las fechas disponibles.", "valor": "", "imagen": "" }, { "id": "museu-historico-cidade", "nombre": "Museu Histórico da Cidade do Rio de Janeiro", "subtitulo": "La historia de Río dentro de un palacete rodeado por el Parque da Cidade", "categoria": "Historia de Río y patrimonio urbano", "descripcion": "El Museu Histórico da Cidade está instalado en el Parque da Cidade, en Gávea. Su conjunto incluye un palacete, un casarón para exposiciones temporales y la Capela de São João Batista. Sus colecciones presentan transformaciones urbanas, personajes, acontecimientos y diferentes formas de representar Río de Janeiro.", "historia": "El origen de la colección se relaciona con iniciativas municipales para reunir objetos, obras y documentos sobre la historia de Río. El museo fue creado durante la primera mitad del siglo XX y posteriormente trasladado al Parque da Cidade.", "direccion": "Estrada Santa Marinha, s/nº – Parque da Cidade – Gávea – Rio de Janeiro – RJ", "horario": "Martes a domingo, de 9:00 a 16:00. Confirma el funcionamiento de la capilla y de las exposiciones temporales.", "valor": "", "imagen": "" }, { "id": "mac-niteroi", "nombre": "Museu de Arte Contemporânea de Niterói – MAC", "subtitulo": "La arquitectura de Oscar Niemeyer suspendida sobre la Baía de Guanabara", "categoria": "Arte contemporáneo y arquitectura", "descripcion": "El MAC de Niterói es uno de los edificios culturales más reconocibles de Brasil. Diseñado por Oscar Niemeyer, su estructura circular parece flotar sobre una base rodeada por un espejo de agua. Las exposiciones de arte contemporáneo se combinan con vistas panorámicas de Niterói, Río y la Baía de Guanabara.", "historia": "El Museu de Arte Contemporânea fue inaugurado el 2 de septiembre de 1996. Desde su apertura, la forma futurista del edificio se convirtió en una de las imágenes más conocidas de Niterói.", "direccion": "Mirante da Boa Viagem, s/nº – Boa Viagem – Niterói – RJ", "horario": "Galerías: martes a domingo, de 10:00 a 18:00, con acceso hasta las 17:30. Plaza exterior: diariamente, normalmente de 9:00 a 18:00.", "valor": "", "imagen": "" }, { "id": "arqueologia-itaipu", "nombre": "Museu de Arqueologia de Itaipu", "subtitulo": "Pueblos originarios, sambaquis y arqueología junto al mar de Niterói", "categoria": "Arqueología y pueblos precoloniales", "descripcion": "El Museu de Arqueologia de Itaipu conserva objetos producidos por pueblos que habitaron el litoral fluminense antes de la llegada de los europeos. Funciona en las ruinas del Recolhimento de Santa Teresa, construcción religiosa del siglo XVIII situada junto a la Praia de Itaipu.", "historia": "Mucho antes de la colonización portuguesa, diferentes pueblos ocuparon las costas de la actual región de Niterói. Dejaron herramientas, restos de alimentos, huesos, pigmentos y grandes acumulaciones conocidas como sambaquis.", "direccion": "Praça de Itaipu, s/nº – Itaipu – Niterói – RJ", "horario": "Martes a viernes, de 11:00 a 16:00, según la ficha oficial vigente. Los horarios de fin de semana pueden variar; confirma antes de desplazarte.", "valor": "", "imagen": "" }];
